<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($umkm['name'])?></title><link rel="stylesheet" href="<?=base_url('public/assets/css/template1.css')?>"></head><body><header><div class="logo">✦ <?=e($umkm['name'])?></div><nav><a href="#home">Home</a><a href="#products">Products</a><a href="#about">About</a><a href="#gallery">Gallery</a><a href="#testi">Testimonials</a><a href="#contact">Contact</a></nav></header><main><section id="home" class="hero"><div><span>FLORAL STUDIO</span><h1><?=e($umkm['hero_title'])?></h1><p><?=e($umkm['hero_text'])?></p><a class="cta" href="#products">Lihat Koleksi</a></div><div class="hero-photo"><?php if($umkm['hero_image']): ?><img src="<?=base_url('public/'.$umkm['hero_image'])?>"><?php else: ?><div>FLOWERS</div><?php endif; ?></div></section><section id="about" class="section"><span>ABOUT US</span><h2><?=e($umkm['name'])?></h2><p><?=e($umkm['description'])?></p></section><section id="products" class="section"><span>OUR COLLECTION</span><h2>Produk Pilihan</h2><div class="cards"><?php foreach($products as $p): ?><article><div class="pic"><?php if($p['image']): ?><img src="<?=base_url('public/'.$p['image'])?>"><?php endif; ?></div><h3><?=e($p['name'])?></h3><p><?=e($p['description'])?></p><b><?=money($p['price'])?></b></article><?php endforeach; ?></div></section><section id="testi" class="section dark"><span>LOVE NOTES</span><h2>Testimonial</h2><div class="cards"><?php foreach($testimonials as $t): ?><article><b><?=str_repeat('★',(int)$t['rating'])?></b><p>“<?=e($t['message'])?>”</p><strong><?=e($t['name'])?></strong></article><?php endforeach; ?></div></section><section id="gallery" class="section"><span>GALLERY</span><h2>Moments in Bloom</h2><div class="gallery"><?php foreach($gallery as $g): ?><img src="<?=base_url('public/'.$g['image'])?>" alt="<?=e($g['title'])?>"><?php endforeach; ?></div></section><section id="contact" class="contact"><h2>Let's create something beautiful.</h2><p><?=e($umkm['address'])?> · <?=e($umkm['hours'])?></p><a class="cta" href="https://wa.me/<?=preg_replace('/\D/','',$umkm['phone'])?>">WhatsApp Kami</a></section></main></body></html>
